mapper.update:
UPDATE dict
name = #{name}, category = #{category}, version = #{version}, status = #{status}, folder_id = #{folderId}, published_at = #{publishedAt}, published_by = #{publishedBy}, review_comment = #{reviewComment}, source = #{source}, source_ref = #{sourceRef},
WHERE id = #{id}

mapper.select:
SELECT d.* FROM dict d
INNER JOIN (
    SELECT dict_key, MAX(version) AS mv FROM dict

    GROUP BY dict_key
) t ON d.dict_key = t.dict_key AND d.version = t.mv
ORDER BY d.id ASC LIMIT #{limit} OFFSET #{offset}
